  "sentences": [
    {
      "id": 1,
      "text": "Revolving credit utilization is the most important driver of default risk, and risk increases as utilization rises."
    },
    {
      "id": 2,
      "text": "The number of past delinquencies is the second most important feature, and risk increases with the count of delinquencies."
    },
    {
      "id": 3,
      "text": "The data do not settle whether the effect of credit utilization and the number of past delinquencies interact."
    },
